import bpy,sys,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];name=sys.argv[sys.argv.index('--')+1];m=json.loads((R/'analysis/trial_manifest.json').read_text());p=Path(m['file']);h=hashlib.sha256(p.read_bytes()).hexdigest();assert h==m['sha256'];bpy.ops.wm.open_mainfile(filepath=str(p));s=bpy.context.scene;s.camera=bpy.data.objects[name];s.render.threads_mode='FIXED';s.render.threads=2;s.cycles.samples=12;s.cycles.use_denoising=False;s.render.resolution_x=1180;s.render.resolution_y=664;s.render.resolution_percentage=50;s.render.image_settings.file_format='PNG';out=R/'renders'/f'{name}.png';s.render.filepath=str(out)
meta={'input':str(p),'sha256_at_load':h,'camera':name,'matrix_world':[list(a) for a in s.camera.matrix_world],'lens':s.camera.data.lens,'resolution':[590,332],'samples':12,'cycles_denoising':False,'threads':2,'visibility_changes':False,'material_changes':False,'trial_not_delivery':True};out.with_suffix('.input.json').write_text(json.dumps(meta,indent=2));bpy.ops.render.render(write_still=True);meta['output_sha256']=hashlib.sha256(out.read_bytes()).hexdigest();meta['sha256_at_end']=hashlib.sha256(p.read_bytes()).hexdigest();assert meta['sha256_at_end']==h;out.with_suffix('.json').write_text(json.dumps(meta,indent=2))
